<?php get_header(); ?><main class="inner-page"><section class="page-hero"><div class="container-xl"><span class="section-kicker">Testimonials</span><h1>What Our Clients Say</h1><p>Read success stories from people who trusted Estatein.</p></div></section><section class="content-section pt-0"><div class="container-xl"><div class="row g-4"><?php if(have_posts()):while(have_posts()):the_post(); ?><div class="col-md-6 col-lg-4"><article class="testimonial-card h-100"><div class="stars"><?php echo str_repeat('★',(int)min(5,max(0,estatein_field('rating',get_the_ID(),5)))); ?></div><h2><?php the_title(); ?></h2><p><?php echo esc_html(estatein_field('testimonial_quote',get_the_ID(),get_the_content())); ?></p><div class="client-meta"><?php echo estatein_image('client_photo','thumbnail',get_the_ID(),'client-avatar'); ?><div><strong><?php echo esc_html(estatein_field('client_name',get_the_ID(),get_the_title())); ?></strong><span><?php echo esc_html(estatein_field('client_location',get_the_ID())); ?></span></div></div></article></div><?php endwhile;else: ?><p>No testimonials found.</p><?php endif; ?></div></div></section></main><?php get_footer(); ?>
